5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
8	
9	/**
10	 * Rejects a create request whose supplied {@code registrationDate} is later than the server's
11	 * current date, so an owner cannot be registered in the future. The date is optional; when omitted
12	 * it defaults to the server date (see {@link ApplyRegistrationDate}), so no check is made then.
13	 */
14	public class ValidateRegistrationDate {
15	
16	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
17	        LocalDate supplied = request.getRegistrationDate();
18	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
19	            throw new FutureRegistrationDateException(
20	                    "registrationDate " + supplied + " must not be later than the server date");
21	        }
22	    }
23	}
