1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
15	 * region derived from the owner's postcode (see {@link CustomerCodeRegion}) and HASH8 is the first
16	 * eight upper-case hex characters of SHA-256 over the concatenation of the owner's normalized (E.164)
17	 * telephone and last name (e.g. {@code NSW-1A2B3C4D}). There is no sequence number, so the code is
18	 * stable for a given telephone/last-name/region and does not depend on how many owners already exist.
19	 * Every value built from the customerCode — the membership number, its check digit, the create audit
20	 * line and the derived locality — follows this region-and-hash identity.
21	 *
22	 * <p>Should the computed code collide with an already-assigned {@code customerCode} (a hash
23	 * collision, or the same region and hash on distinct owners), it is de-duplicated by appending
24	 * {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique among existing owners.
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String code = CustomerCodeRegion.of(owner) + "-" + hash8(owner);
30	        owner.setCustomerCode(deduplicate(code, ownerRepository));
31	    }
32	
33	    /**
34	     * Returns {@code code} unchanged when no existing owner already uses it, otherwise
35	     * {@code code-<n>} with the smallest {@code n >= 2} that is not already in use.
36	     */
37	    private static String deduplicate(String code, OwnerRepository ownerRepository) {
38	        Set<String> existing = new HashSet<>();
39	        for (Owner other : ownerRepository.findAll()) {
40	            if (other.getCustomerCode() != null) {
41	                existing.add(other.getCustomerCode());
42	            }
43	        }
44	        if (!existing.contains(code)) {
45	            return code;
46	        }
47	        for (int n = 2; ; n++) {
48	            String candidate = code + "-" + n;
49	            if (!existing.contains(candidate)) {
50	                return candidate;
51	            }
52	        }
53	    }
54	
55	    /** First eight upper-case hex characters of SHA-256(normalizedTelephone + lastName). */
56	    private static String hash8(Owner owner) {
57	        // The stored telephone is already E.164 (see NormalizeOwnerTelephone); re-normalizing is
58	        // idempotent and falls back to the stored value if it somehow cannot be parsed.
59	        String normalizedTelephone = E164Telephone.toE164OrNull(owner.getTelephone());
60	        if (normalizedTelephone == null) {
61	            normalizedTelephone = owner.getTelephone() == null ? "" : owner.getTelephone();
62	        }
63	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
64	        try {
65	            byte[] digest = MessageDigest.getInstance("SHA-256")
66	                    .digest((normalizedTelephone + lastName).getBytes(StandardCharsets.UTF_8));
67	            StringBuilder sb = new StringBuilder(8);
68	            for (int i = 0; i < 4; i++) {
69	                sb.append(String.format("%02X", digest[i]));
70	            }
71	            return sb.toString();
72	        }
73	        catch (NoSuchAlgorithmException e) {
74	            throw new IllegalStateException("SHA-256 unavailable", e);
75	        }
76	    }
77	}
